<?php require __DIR__.'/bootstrap.php';require_admin();$orders=read_json('orders.json',[]);$message='';$statuses=['Order Confirmed','Preparing','Ready for Pickup/Dispatch','Out for Delivery','Delivered','Cancelled','Refund Pending','Refunded'];if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$ref=(string)($_POST['reference']??'');$status=(string)($_POST['status']??'');if(in_array($status,$statuses,true)){foreach($orders as &$o)if($o['reference']===$ref){$o['status']=$status;$o['timeline'][]=['status'=>$status,'at'=>date(DATE_ATOM)];$message='Order status updated.';add_notification('Order updated',$ref.' status changed to '.$status,'order',$ref);if(($o['payment_status']??'')==='paid'){send_order_email($o,true);}break;}unset($o);write_json('orders.json',$orders);}}site_header('Manage orders'); ?>
<div class="admin-shell"><div class="eyebrow">Owner workspace</div><h1 style="font:42px 'Playfair Display',serif">Orders</h1><nav class="admin-nav"><a href="admin.php">Overview</a><a href="admin-products.php">Products</a><a href="admin-orders.php">Orders</a><a href="admin-settings.php">Settings</a><a href="admin-gallery.php">Gallery</a><a href="admin-notifications.php">Notifications</a><a href="admin-subscribers.php">Newsletter</a><a href="admin-requests.php">Custom requests</a><a href="admin-logout.php">Sign out</a></nav><?php if($message)echo '<div class="alert success">'.e($message).'</div>'; ?><div class="card-panel table-wrap"><table class="data-table"><thead><tr><th>Order</th><th>Customer</th><th>Items / fulfilment</th><th>Total</th><th>Payment</th><th>Update status</th></tr></thead><tbody><?php foreach(array_reverse($orders) as $o): ?><tr><td><strong><?= e($o['reference']) ?></strong><br><small><?= e(date('j M Y H:i',strtotime($o['created_at']))) ?></small><br><a class="text-link" href="track.php?reference=<?= urlencode($o['reference']) ?>" target="_blank">View receipt</a></td><td><?= e($o['customer']['name']??'') ?><br><a href="mailto:<?= e($o['customer']['email']??'') ?>"><?= e($o['customer']['email']??'') ?></a><br><?= e($o['customer']['phone']??'') ?></td><td><?php foreach($o['items'] as $i)echo e($i['name']).' × '.(int)$i['qty'].'<br>'; ?><?= e($o['fulfilment']) ?><br><?= e($o['scheduled_at']) ?></td><td><?= money((float)$o['total']) ?></td><td><span class="status <?= e($o['payment_status']) ?>"><?= e($o['payment_status']) ?></span></td><td><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="reference" value="<?= e($o['reference']) ?>"><select name="status"><?php foreach($statuses as $s): ?><option <?= $s===$o['status']?'selected':'' ?>><?= e($s) ?></option><?php endforeach; ?></select><button class="button button-small" type="submit">Update</button></form></td></tr><?php endforeach; ?></tbody></table><?php if(!$orders)echo '<p>No orders yet.</p>'; ?></div></div><?php site_footer(); ?>
